<script>
  var current = 1, TOTAL = 3;
  var labels = {1:'Account', 2:'Preferences', 3:'Done'};

  function $(id){ return document.getElementById(id); }

  function render(){
    // panels
    document.querySelectorAll('.wiz-panel').forEach(function(p){
      p.classList.toggle('active', +p.dataset.panel === current);
    });
    // stepper
    document.querySelectorAll('#stepper .step').forEach(function(s){
      var n = +s.dataset.step;
      s.classList.toggle('active', n === current);
      s.classList.toggle('done', n < current);
      s.querySelector('.step-dot').textContent = n < current ? '✓' : n;
    });
    // progress
    var pct = Math.round(current / TOTAL * 100);
    $('progressBar').style.width = pct + '%';
    $('progressPct').textContent = pct + '%';
    $('progressLabel').textContent = 'Step ' + current + ' of ' + TOTAL + ' — ' + labels[current];

    // controls
    $('backBtn').style.visibility = current === 1 ? 'hidden' : 'visible';
    $('nextBtn').textContent = current === 1 ? 'Continue →'
                             : current === 2 ? 'Finish setup ✓'
                             : 'Go to dashboard →';
    $('stepHint').textContent = current === 1 ? 'Fields marked are required to continue.'
                              : current === 2 ? 'Optional — sensible defaults are pre-selected.'
                              : 'Nothing left to do. Welcome aboard!';
  }

  function validateAccount(){
    var errs = [];
    var name = $('fName').value.trim();
    var email = $('fEmail').value.trim();
    if(!name) errs.push('your full name');
    if(!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errs.push('a valid work email');
    if(!$('fTerms').checked) errs.push('acceptance of the Terms of Service');

    var box = $('accountError');
    if(errs.length){
      box.style.display = 'block';
      box.textContent = 'Before continuing, please provide: ' + errs.join(', ') + '.';
      return false;
    }
    box.style.display = 'none';
    return true;
  }

  function fillSummary(){
    var notif = [];
    if($('pN1').checked) notif.push('Product updates');
    if($('pN2').checked) notif.push('Weekly digest');
    if($('pN3').checked) notif.push('Mentions only');
    $('sName').textContent    = $('fName').value.trim() || '—';
    $('sEmail').textContent   = $('fEmail').value.trim() || '—';
    $('sCompany').textContent = $('fCompany').value.trim() || '—';
    $('sTeam').textContent    = $('fTeamSize').value;
    $('sLang').textContent    = $('pLang').value;
    $('sTz').textContent      = $('pTz').value;
    $('sTheme').textContent   = document.querySelector('input[name="theme"]:checked').value;
    $('sNotif').textContent   = notif.length ? notif.join(' · ') : 'None';
    var first = ($('fName').value.trim().split(' ')[0]) || 'friend';
    $('doneName').textContent = first;
    $('doneEmail').textContent = $('fEmail').value.trim() || 'your inbox';
  }

  function go(dir){
    if(dir > 0){
      if(current === 1 && !validateAccount()) return;
      if(current === 2) fillSummary();
      if(current === 3){
        var note = $('finalNote');
        note.style.display = 'block';
        note.innerHTML = '<strong>This is the end of the demo wizard.</strong> In production, this button would route you to your new dashboard.';
        return;
      }
      current = Math.min(current + 1, TOTAL);
    } else {
      current = Math.max(current - 1, 1);
    }
    render();
    window.scrollTo({top:0, behavior:'smooth'});
  }

  // Enter key advances instead of submitting
  document.addEventListener('keydown', function(e){
    if(e.key === 'Enter' && e.target.tagName !== 'BUTTON'){ e.preventDefault(); go(1); }
  });

  render();
</script>
